function resolve(template, scopes) {
  return template.replace(/\{\{([^{}]+)\}\}/g, (match, name) => {
    for (const scope of scopes) {
      if (Object.prototype.hasOwnProperty.call(scope, name)) return String(scope[name]);
    }
    return match;
  });
}
